"""Model of Virus's landscape height field: sum of eight sines, generated by the routine at $23414
calling $245b8 for each of 256x256 cells, stored as bytes at $42a58 (index = (y<<8)|x).
Usage: python virus_terrain.py <snap> [--break]   (compares the model with the snapshot's RAM; the level
variant is read from the word at $32a4e: 0, 1, else).
"""
import math, os, struct, sys

def find_root():
    d = os.path.dirname(os.path.abspath(__file__))
    while not os.path.exists(os.path.join(d, 'tools', 'rdis.py')):
        p = os.path.dirname(d)
        if p == d:
            raise SystemExit('repo root not found')
        d = p
    return d

def sext16(v):
    v &= 0xffff
    return v - 0x10000 if v & 0x8000 else v

def sine_table():
    # truncation toward zero (int), not round(): 1024/1024 vs the RAM table at $d0fa; the peak entry 256 is
    # 32766 where int() gives 32767 (the one odd entry)
    t = [int(32767 * math.sin(2 * math.pi * k / 1024)) for k in range(1024)]
    t[256] = 32766
    return t

# per-level patches written into $245b8 at $24680..$24688 and $24756 by the code at $2336a
# (shift after the sum, whether the second neg is a nop, base added, edge limit)
VARIANTS = {0: dict(shift=7, base=0x520, edge=0x900, neg1=True, neg2=False),
            1: dict(shift=6, base=0x700, edge=0x900, neg1=False, neg2=False),
            2: dict(shift=6, base=0x600, edge=0x900, neg1=True, neg2=True)}

def height_d1(x, y, S, v, sk=1):
    """Return D1 (word, signed) as $245b8 leaves it, for x=D6, y=D7 (unsigned 16-bit)."""
    x &= 0xffff; y &= 0xffff
    def s(ang, sh):
        return sext16(S[(ang & 0xffff) >> 6]) >> sh
    D4 = (x * 2) & 0xffff; D5 = (y * 2) & 0xffff
    D2 = (D4 * 2) & 0xffff; D3 = (D5 * 2) & 0xffff
    a1 = sext16(S[((x - D5) & 0xffff) >> 6])
    a1 += s(D4 + y + x, 0)
    a1 += s(D5 - D4 + y, 0)
    a1 += s(D2 - D3 - y, 1)
    a1 += s(D5 - D2 - x, 1)
    a1 += s(D2 + D4 + D3 + y, 1)
    d2 = (2 * D2 + x + D4) & 0xffff
    a1 += s(d2 - D3 - D5 - y, 2)
    a1 += s(2 * D3 + d2 + D5 + y, 2)
    d1 = sext16(a1 >> v['shift'])
    if v['neg1']:
        d1 = sext16(-d1)
    return d1

def model_byte(x, y, S, v):
    """The byte stored at $42a58 + (y>>8<<8) + (x>>8)."""
    if x < v['edge'] and y < 0x900:
        d1 = 0x420          # edge/launch-pad region (table at $246ba, not modelled: only 9x9 cells)
        return None
    d1 = height_d1(x, y, S, v)
    # $24684 bmi $24688 ; $24686 nop|neg.w
    if d1 >= 0 and v['neg2']:      # $24684 bmi $24688 skips the word at $24686 when D1 is negative
        d1 = sext16(-d1)
    d1 = (d1 + v['base']) & 0xffff
    d1s = sext16(d1)
    if d1s > 0x510:
        if d1s > 0x560:
            d1s = 0x560
    d1 = d1s & 0xffff
    return (((d1 - 0xfd61) & 0xffff) >> 3) & 0xff

def main():
    root = find_root(); sys.path.insert(0, os.path.join(root, 'tools'))
    import gfxview
    ram, _ = gfxview.load_ram(sys.argv[1]); r = bytearray(ram)
    if '--delta' in sys.argv:        # a callcap json: apply its memory delta [addr, before, after] to the snapshot RAM
        import json
        for a, _b, af in json.load(open(sys.argv[sys.argv.index('--delta') + 1]))['mem']:
            r[a] = af
    r = bytes(r)
    force = int(sys.argv[sys.argv.index('--level') + 1]) if '--level' in sys.argv else None
    Sram = list(struct.unpack('>1024h', r[0xd0fa:0xd0fa + 2048]))
    S = sine_table()                       # the gate uses the model's own table
    print('model sine table == RAM table at $d0fa:', sum(1 for a, b in zip(S, Sram) if a == b), '/1024')
    lvl = struct.unpack('>H', r[0x32a4e:0x32a50])[0]
    if force is not None: lvl = force
    v = dict(VARIANTS[0 if lvl == 0 else 1 if lvl == 1 else 2])
    if '--break' in sys.argv:
        v['base'] += 8
    ok = bad = skip = 0
    for cy in range(256):
        for cx in range(256):
            m = model_byte(cx << 8, cy << 8, S, v)
            if m is None:
                skip += 1; continue
            if m == r[0x42a58 + (cy << 8) + cx]: ok += 1
            else: bad += 1
    print(f'level {lvl}: match {ok}/{ok+bad} (edge cells skipped {skip})')

if __name__ == '__main__':
    main()
